from research_helpers import *
a=ev('https://care360.basf.com/emea/en/industries/home-care-and-i-i/Segements---Sustainable-Solutions/homecare/Lavergy--Enzymes','Ten explicit current liquid detergent enzyme grades reviewed; no umbrella family duplicated.')
b=ev('https://download.basf.com/p1/EN_StaticDocuments_5741/en/Animal_Nutrition_Product_Catalog','May 2025 official catalogue enzyme tables reviewed. Two ambiguous typography entries held; regional registration required, not global approval.')
c=ev('https://www.basf.com/global/en/media/news-releases/2016/10/p-16-328','Historical Pro104L identity; current availability unresolved.')
d=ev('https://nutrition.basf.com/global/en/animal-nutrition/our-products/enzymes','Original Natuphos historical phytase distinct from current hybrid Natuphos E.')
e=ev('https://care360.basf.com/global/en/sustainability/renewables_neu/Bio-based-Solutions','Plantigenix Bisabolol explicitly produced by precision fermentation; other ordinary biobased surfactants not automatically included.')
products=[]
for name,desc in [('B Magic 300 L','Cleaning enzyme blend.'),('B Magic 400 L','Cleaning enzyme blend.'),('Pro 106 L','Unstabilized liquid protease.'),('Pro 106 LS','Stabilized liquid protease.'),('Pro 114 LS','Boron-free stabilized protease.'),('A Star 200 L','Liquid amylase.'),('L Pace 100 L','Liquid lipase.'),('M Ace 200 L','Liquid mannanase.'),('C Care 100 L','Fabric-care cellulase.'),('C Bright 100 L','Anti-greying cellulase.')]:products.append(p('Lavergy '+name,desc,a,life='commercial',typ='product',sub='industrial_biotechnology',roles=['commercial_partner']))
for name in ['5000','10000','50000','5000 L','10000 L','15000 L','25000 L','5000 G','10000 G','17500 G']:
 products.append(p('Natuphos E '+name,'Feed phytase.',b,life='commercial',typ='product',sub='industrial_biotechnology',roles=['commercial_partner']))
for name in ['5000 Combi L','5000 Combi G','10000 Combi G']:products.append(p('Natuphos E '+name,'Feed enzyme blend.',b,life='commercial',typ='product',sub='industrial_biotechnology',roles=['commercial_partner']))
for name in ['Natugrain Wheat TS','Natugrain TS','Natugrain TS 5XG','Natugrain TS L','Natugrain TS DL','Natupulse TS','Natupulse TS L','Natupulse TS 5M']:products.append(p(name,'Feed enzyme formulation.',b,life='commercial',typ='product',sub='industrial_biotechnology',roles=['commercial_partner']))
products += [p('Lavergy Pro 104 L','Historical liquid protease grade; current availability unresolved.',c,typ='product',sub='industrial_biotechnology',roles=['commercial_partner']),p('Natuphos','Historical original feed phytase product; distinct from Natuphos E hybrid successor. Current original-product availability unresolved.',d,typ='product',sub='industrial_biotechnology',roles=['commercial_partner']),p('Plantigenix Bisabolol','Precision-fermentation bisabolol ingredient for cosmetic formulations.',e,life='commercial',typ='product',sub='industrial_biotechnology',roles=['commercial_partner'])]
co=dict(company_id='cmp_2fa8cc21-8e08-4f1b-aa3c-3cdc02359ffa',products=products,evidence=[a,b,c,d,e],status='partial',coverage_note='42 BASF offerings total: eight cathode materials plus ten current Lavergy grades, 21 exact feed-enzyme formulations, two historical enzyme products and fermentation bisabolol. Regional feed registrations not extrapolated worldwide; Natupulse superscript footnote excluded from names. Ambiguous Natuphos E20000Gb and catalogue Nautugrain TS2.5G typography held pending verification. Partial: further biotech/fermentation products/platforms, semiconductor chemicals, battery binders/electrolytes/recycling technologies, historical storage systems and legacy portfolio remain.')
assert len(products)==34
(out/'batch-0390.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
